149	// buildDocsResponse lists the doc sections that point, one hop, at something
150	// the working tree changed relative to HEAD:
151	//
152	//   - a section that MENTIONS a changed or removed code symbol, or a changed file;
153	//   - a section that LINKS_TO a changed or removed section, or a changed file;
154	//   - a Markdown file that usually changes with a changed file (FILE_CHANGES_WITH)
155	//     but was not touched.
156	//
157	// Mentions and links are read from both snapshots: the HEAD one is what still
158	// records a mention of a symbol the change removed or renamed. A section the
159	// change already edited is counted as updated rather than listed.
160	func buildDocsResponse(base, head sem.ProviderSnapshot, readBase, readHead lineReader, limit int) docsResponse {
161		response := docsResponse{BaseCommit: base.Header.Commit, Items: []docsItem{}}
162	
163		baseFiles := map[string]sem.FileRecord{}
164		for _, file := range base.Files {
165			baseFiles[file.Path] = file
166		}
167		headFiles := map[string]sem.FileRecord{}
168		headFilePaths := map[string]string{}
169		for _, file := range head.Files {
170			headFiles[file.Path] = file
171			headFilePaths[file.ID] = file.Path
172		}
173		changedFiles := map[string]bool{}
174		for path, file := range headFiles {
175			if before, ok := baseFiles[path]; !ok || before.Blob != file.Blob {
176				changedFiles[path] = true
177			}
178		}
179		for path := range baseFiles {
180			if _, ok := headFiles[path]; !ok {
181				changedFiles[path] = true
182			}
183		}
184		response.ChangedFiles = len(changedFiles)
185		if len(changedFiles) == 0 {
186			return response
187		}
188		changedFileIDs := map[string]string{}
189		// A doc that names or links a file by path goes stale when the path stops
190		// existing, not whenever the file's content changes: a section naming
191		// `CLAUDE.md` describes the file's role, not its text. Content changes are
192		// caught precisely through symbol mentions and anchored section links.
193		removedFileIDs := map[string]bool{}
194		for path := range changedFiles {
195			if file, ok := headFiles[path]; ok {
196				changedFileIDs[file.ID] = path
197			} else {
198				changedFileIDs[baseFiles[path].ID] = path
199				removedFileIDs[baseFiles[path].ID] = true
200			}
201		}
202	
203		headSymbols := map[string]sem.SymbolRecord{}
204		for _, symbol := range head.Symbols {
205			headSymbols[symbol.ID] = symbol
206		}
207		baseSymbols := map[string]sem.SymbolRecord{}
208		for _, symbol := range base.Symbols {
209			baseSymbols[symbol.ID] = symbol
210		}
211	
212		// Code symbols whose body changed or that the change removed. Added symbols
213		// are left out: no existing doc can describe them yet.
214		codeChanges := map[string]string{}
215		for id, before := range baseSymbols {
216			if !changedFiles[before.FilePath] || before.Language == "Markdown" {
217				continue
218			}
219			if after, ok := headSymbols[id]; !ok {
220				codeChanges[id] = "removed"
221			} else if after.BodyHash != before.BodyHash {
222				codeChanges[id] = "changed"
223			}
224		}
225		response.ChangedSymbols = len(codeChanges)
226	
227		sectionChanges := changedDocSections(base, head, changedFiles, baseFiles, headFiles, readBase, readHead)
228	
229		items := map[string]*docsItem{}
230		alreadyUpdated := map[string]bool{}
231		addReason := func(fromID string, reason docsReason) {
232			if sectionChanges[fromID] != "" {
233				alreadyUpdated[fromID] = true
234				return
235			}
236			item := items[fromID]
237			if item == nil {
238				var ok bool
239				if item, ok = docsItemFor(fromID, headSymbols, headFilePaths); !ok {
240					return
241				}
242				items[fromID] = item
243			}
244			for _, existing := range item.Reasons {
245				if existing == reason {
246					return
247				}
248			}
249			item.Reasons = append(item.Reasons, reason)
250		}
251		targetOf := func(id string) (target, path string) {
252			if path, ok := changedFileIDs[id]; ok {
253				return path, path
254			}
255			symbol, ok := headSymbols[id]
256			if !ok {
257				symbol = baseSymbols[id]
258			}
259			name := symbol.QualifiedName
260			if name == "" {
261				name = symbol.Name
262			}
263			if symbol.Kind == "section" {
264				name = symbol.FilePath + "#" + docsHeading(symbol)
265			}
266			return name, symbol.FilePath
267		}
268	
269		for _, relations := range [][]sem.RelationRecord{head.Relations, base.Relations} {
270			for _, relation := range relations {
271				switch relation.Type {
272				case sem.MarkdownMentionsRelation:
273					change := codeChanges[relation.ToID]
274					if change == "" && removedFileIDs[relation.ToID] {
275						change = "removed"
276					}
277					if change != "" {
278						target, path := targetOf(relation.ToID)
279						addReason(relation.FromID, docsReason{Kind: "mentions", Target: target, Path: path, Change: change})
280					}
281				case sem.MarkdownLinksToRelation:
282					// sectionChanges also keys a document's preamble by its file ID, so
283					// only a section target reads it; a file target follows the
284					// removed-path rule above.
285					change := ""
286					if relation.TargetKind == "symbol" {
287						change = sectionChanges[relation.ToID]
288					} else if removedFileIDs[relation.ToID] {
289						change = "removed"
290					}
291					if change != "" {
292						target, path := targetOf(relation.ToID)
293						addReason(relation.FromID, docsReason{Kind: "links", Target: target, Path: path, Change: change})
294					}
295				}
