1	package sem
2	
3	import (
4		"net/url"
5		"path"
6		"regexp"
7		"sort"
8		"strconv"
9		"strings"
10		"unicode"
11	)
12	
13	// Markdown prose relations. They are experimental, so they carry the provider
14	// namespace ADR 0001 rule 4 reserves for that: the shape can change without a
15	// schema major, and a tolerant reader that does not know them ignores them.
16	const (
17		// MarkdownMentionsRelation runs from a Markdown section (or the file, for the
18		// preamble above its first heading) to a code symbol or repository file the
19		// prose names in inline code.
20		MarkdownMentionsRelation = "X-entire-graph:MENTIONS"
21		// MarkdownLinksToRelation runs from a Markdown section to the repository file,
22		// or the section of one, that a Markdown link points at.
23		MarkdownLinksToRelation = "X-entire-graph:LINKS_TO"
24	)
25	
26	var (
27		markdownLinkRe         = regexp.MustCompile(`(!?)\[[^\]]*\]\(\s*<?([^)\s>]+)>?(?:\s+["'][^)]*["'])?\s*\)`)
28		markdownLinkSchemeRe   = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9+.-]*:`)
29		markdownMentionIdentRe = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)*$`)
30	)
31	
32	// markdownRelations emits MENTIONS and LINKS_TO for every Markdown file in
33	// recordsByFile. Lines inside code fences are code, not prose, and are skipped:
34	// a fenced shell session names commands, not the symbols a section is about.
35	//
36	// MENTIONS resolves an inline code span two ways. A span that is a repository
37	// path (optionally `:line`) names that file exactly. A span shaped like an
38	// identifier (`Name`, `Name()`, `pkg.Name`, `Type.Member`) resolves against the
39	// workspace's code symbols by short name and only when exactly one candidate
40	// survives, so `Run` with three definitions names nothing rather than the one
41	// that sorts first. Spans that read as ordinary words (`query`, `index`) are
42	// not names at all and are skipped.
43	func markdownRelations(repoKey string, recordsByFile map[string][]SymbolRecord, symbolsByShortName map[string][]SymbolRecord, knownFiles map[string]bool, readContent contentReader, spec profileSpec) []RelationRecord {
44		paths := make([]string, 0, len(recordsByFile))
45		for docPath := range recordsByFile {
46			paths = append(paths, docPath)
47		}
48		sort.Strings(paths)
49	
50		anchorsByFile := map[string]map[string]string{}
51		anchors := func(file string) map[string]string {
52			if found, ok := anchorsByFile[file]; ok {
53				return found
54			}
55			found := markdownSectionAnchors(recordsByFile[file])
56			anchorsByFile[file] = found
57			return found
58		}
59	
60		var relations []RelationRecord
61		seen := map[string]bool{}
62		add := func(relation RelationRecord) {
63			key := relation.FromID + "\x00" + relation.ToID + "\x00" + relation.Type
64			if relation.FromID == relation.ToID || seen[key] {
65				return
66			}
67			seen[key] = true
68			relations = append(relations, relation)
69		}
70		// Resolution scans every same-named definition, and a document is free to
71		// repeat a span thousands of times, so each distinct span resolves once.
72		type mentionTarget struct {
73			toID, targetKind, resolution string
74			confidence                   float64
75			ok                           bool
76		}
77		mentionTargets := map[string]mentionTarget{}
78		for _, docPath := range paths {
79			content, ok := readContent(docPath)
80			if !ok {
81				continue
82			}
83			sectionsByLine := map[int]string{}
84			for _, symbol := range recordsByFile[docPath] {
85				if symbol.Kind == "section" && symbol.StartLine > 0 {
86					sectionsByLine[symbol.StartLine] = symbol.ID
87				}
88			}
89			headingLines := proseSectionHeadingLines(recordsByFile[docPath])
90			lines := strings.Split(content, "\n")
91			inFence := markdownFenceLines(lines)
92			for index, line := range lines {
93				if inFence[index] {
94					continue
95				}
96				lineNumber := index + 1
97				from := fileID(repoKey, docPath)
98				if heading := proseSectionHeadingAt(headingLines, lineNumber); heading > 0 {
99					from = sectionsByLine[heading]
100				}
101				spans, prose := markdownCodeSpans(line)
102				if spec.emits(MarkdownMentionsRelation) {
103					for _, span := range spans {
104						target, resolved := mentionTargets[span]
105						if !resolved {
106							target.toID, target.targetKind, target.resolution, target.confidence, target.ok = markdownMentionTarget(repoKey, span, knownFiles, symbolsByShortName)
107							mentionTargets[span] = target
108						}
109						if !target.ok {
110							continue
111						}
112						add(markdownRelation(from, target.toID, MarkdownMentionsRelation, target.confidence, "Markdown names this in inline code", target.resolution, target.targetKind, "inline_code", docPath, lineNumber, span))
113					}
114				}
115				if spec.emits(MarkdownLinksToRelation) {
116					for _, match := range markdownLinkRe.FindAllStringSubmatch(prose, -1) {
117						if match[1] == "!" {
118							continue
119						}
120						toID, targetKind, ok := markdownLinkTarget(repoKey, docPath, match[2], knownFiles, anchors)
121						if !ok {
122							continue
123						}
124						add(markdownRelation(from, toID, MarkdownLinksToRelation, 1, "Markdown link", "exact", targetKind, "link", docPath, lineNumber, match[2]))
125					}
126				}
127			}
128		}
129		return relations
130	}
131	
132	func markdownRelation(from, to, relationType string, confidence float64, reason, resolution, targetKind, evidenceKind, docPath string, line int, detail string) RelationRecord {
133		return RelationRecord{
134			RecordType:    "relation",
135			FromID:        from,
136			ToID:          to,
137			Type:          relationType,
138			Confidence:    confidence,
139			Reason:        reason,
140			RelationScope: "workspace",
141			Resolution:    resolution,
142			TargetKind:    targetKind,
143			Evidence: []Evidence{{
144				Kind:      evidenceKind,
145				FilePath:  docPath,
146				StartLine: line,
147				EndLine:   line,
148				Detail:    detail,
149			}},
150			WarningCodes: []string{},
151		}
152	}
153	
154	func markdownMentionTarget(repoKey, span string, knownFiles map[string]bool, symbolsByShortName map[string][]SymbolRecord) (toID, targetKind, resolution string, confidence float64, ok bool) {
155		if file, _, _ := strings.Cut(span, ":"); knownFiles[file] {
156			return fileID(repoKey, file), "file", "exact", 0.9, true
157		}
158		name, called := strings.CutSuffix(span, "()")
159		if !markdownMentionIdentRe.MatchString(name) {
160			return "", "", "", 0, false
161		}
162		qualifier, short := "", name
163		if dot := strings.LastIndex(name, "."); dot >= 0 {
164			qualifier, short = name[:dot], name[dot+1:]
165		}
166		if !markdownMentionDistinctive(short, qualifier != "" || called) {
167			return "", "", "", 0, false
168		}
169		var candidates []SymbolRecord
170		for _, symbol := range symbolsByShortName[short] {
171			if !markdownMentionTargetKind(symbol.Kind) {
172				continue
173			}
174			// A qualifier must agree with the candidate: `Result.Field` names the
175			// member of Result, and `sem.Func` names the function in package sem.
176			if qualifier != "" && symbol.QualifiedName != name && !strings.HasSuffix(symbol.QualifiedName, "."+name) && path.Base(path.Dir(symbol.FilePath)) != qualifier {
177				continue
178			}
179			candidates = append(candidates, symbol)
180		}
181		if len(candidates) != 1 {
182			return "", "", "", 0, false
183		}
184		return candidates[0].ID, "symbol", "name_only", 0.6, true
185	}
186	
